<?php require_once __DIR__.'/../_init.php';if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM gallery WHERE id=?')->execute([(int)$_GET['delete']]);redirect('index.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$f=save_upload('image','gallery');if($f)$pdo->prepare('INSERT INTO gallery(file_path,caption,urutan) VALUES(?,?,?)')->execute([$f,trim($_POST['caption']),1]);redirect('index.php');}$rows=$pdo->query('SELECT * FROM gallery ORDER BY urutan,id')->fetchAll();admin_header('Gallery');?><div class="admin-card"><h1>Gallery</h1><form method="post" enctype="multipart/form-data" class="form"><?=csrf_field()?><input type="file" name="image" accept="image/*" required><input name="caption" placeholder="Caption"><button class="btn">Upload</button></form></div><div class="gallery"><?php foreach($rows as $r):?><div><img src="<?=e(public_image($r['file_path']))?>"><a href="?delete=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></div><?php endforeach;?></div><?php admin_footer();?>
